    static func contains(latitude: Double, longitude: Double) -> Bool {
        guard latitude > -90, latitude < 90 else { return false }
        var longitude = longitude
        while longitude < -180 { longitude += 360 }
        while longitude >= 180 { longitude -= 360 }

        let column = Int(((longitude + 180) / degreesPerCell).rounded(.down))
        let row = Int(((90 - latitude) / degreesPerCell).rounded(.down))
        guard column >= 0, column < width, row >= 0, row < height else { return false }

        let index = row * width + column
        return bits[index / 8] & (1 << (7 - (index % 8))) != 0
    }

    /// True when any land cell falls inside the box. Coarse dots use this so a
    /// wide step still fills a continent instead of skipping between samples.
    static func coversLand(latitude: Double, longitude: Double, halfSpan: Double) -> Bool {
        if halfSpan <= degreesPerCell * 0.51 {
            return contains(latitude: latitude, longitude: longitude)
        }

        var latitudeCursor = latitude - halfSpan
        let latitudeEnd = latitude + halfSpan
        while latitudeCursor <= latitudeEnd {
            var longitudeCursor = longitude - halfSpan
            let longitudeEnd = longitude + halfSpan
            while longitudeCursor <= longitudeEnd {
                if contains(latitude: latitudeCursor, longitude: longitudeCursor) {
                    return true
                }
                longitudeCursor += degreesPerCell
            }
            latitudeCursor += degreesPerCell
        }
        return false
    }
